import 'dart:io';import 'package:drift/drift.dart';import 'package:drift/native.dart';import 'package:path_provider/path_provider.dart';import '../../../core/database/drift_executor_opener.dart';import 'favorite.dart';
class FavoritesRepository { FavoritesRepository(this.e);final QueryExecutor e;var ready=false;static Future<FavoritesRepository> open()async{final d=await getApplicationSupportDirectory();final x=FavoritesRepository(NativeDatabase(File('${d.path}${Platform.pathSeparator}swapo.sqlite')));await x.init();return x;}Future<void> init()async{if(ready)return;await ensureDriftExecutorOpen(e);await e.runCustom('CREATE TABLE IF NOT EXISTS favorites (user_id INTEGER NOT NULL,type TEXT NOT NULL,item_id INTEGER NOT NULL,title TEXT NOT NULL,PRIMARY KEY(user_id,type,item_id))');ready=true;}Future<List<Favorite>> list(int userId)async{await init();final r=await e.runSelect('SELECT type,item_id,title FROM favorites WHERE user_id=? ORDER BY title',[userId]);return r.map((x)=>Favorite(type:x['type']! as String,itemId:x['item_id']! as int,title:x['title']! as String)).toList();}Future<void> toggle(int userId,Favorite f)async{await init();final exists=await e.runSelect('SELECT 1 FROM favorites WHERE user_id=? AND type=? AND item_id=?',[userId,f.type,f.itemId]);if(exists.isEmpty){await e.runInsert('INSERT INTO favorites(user_id,type,item_id,title) VALUES(?,?,?,?)',[userId,f.type,f.itemId,f.title]);}else{await e.runDelete('DELETE FROM favorites WHERE user_id=? AND type=? AND item_id=?',[userId,f.type,f.itemId]);}}}
